 SELECT COUNT(*) INTO pir_count FROM zsjos_order_approval_round x JOIN pir_plan p ON p.table_name='zsjos_order_approval_round' AND p.row_id=x.id WHERE x.tenant_id=1 FOR UPDATE;
 UPDATE pir_plan p JOIN zsjos_order_approval_round x ON p.table_name='zsjos_order_approval_round' AND p.row_id=x.id AND x.tenant_id=1 SET p.current_image=JSON_OBJECT('id',x.`id`,'tenant_id',x.`tenant_id`,'deleted',CAST(x.`deleted` AS UNSIGNED),'order_id',x.`order_id`,'order_snapshot',CAST(x.`order_snapshot` AS JSON),'version',x.`version`,'updater',x.`updater`,'update_time',DATE_FORMAT(x.`update_time`,'%Y-%m-%d %H:%i:%s.%f'));

